def scale_time_units(time_seconds_arr, unit):
    """
    Convert an array of time durations in seconds to the specified time unit.
    """
    if unit == 'minutes':
        return list(map(lambda x: x * 1.0 / 60, time_seconds_arr))
    elif unit == 'hours':
        return list(map(lambda x: x * 1.0 / (60 * 60), time_seconds_arr))
    elif unit == 'days':
        return list(map(lambda x: x * 1.0 / (24 * 60 * 60), time_seconds_arr))
    return time_seconds_arr

def mk_constant(cnst_syc):
    '''
    Create a python value from a BridgePoint constant.
    '''
    s_dt = one(cnst_syc).S_DT[1500]()
    cnst_lsc = one(cnst_syc).CNST_LFSC[1502].CNST_LSC[1503]()

    if s_dt.Name == 'boolean':
        return cnst_lsc.Value.lower() == 'true'

    if s_dt.Name == 'integer':
        return int(cnst_lsc.Value)

    if s_dt.Name == 'real':
        return float(cnst_lsc.Value)

    if s_dt.Name == 'string':
        return str(cnst_lsc.Value)

def compare_content_type(url, content_type):
    '''
    Compare the content type header of url param with content_type param and returns boolean 
    @param url -> string e.g. http://127.0.0.1/index
    @param content_type -> string e.g. text/html
    '''
    try:    
        response = urllib2.urlopen(url)
    except:
        return False

    return response.headers.type == content_type

